  font-weight: bold;
}

th {
  text-align: left;
  color: #5a3e2b;
}

nav {
  text-align: center;
  display: flex;
  gap: 16px;
  justify-content: center;
}

img {
  border-radius: 12px;
}

th, td {
  padding: 6px;
}

header {
  background-color: #5a3e2b;
  padding: 16px;
}

header h1, header p {
